9	use AtrioTeam\DigitalHub\Assets\Support\AssetZip;
10	use Illuminate\Http\Request;
11	use Illuminate\Support\Facades\Gate;
12	use Illuminate\Support\Facades\Storage;
13	use Spatie\MediaLibrary\MediaCollections\Models\Media;
14	use Symfony\Component\HttpFoundation\Response;
15	use Symfony\Component\HttpFoundation\StreamedResponse;
16	
17	/**
18	 * Serving gated degli asset (digital-hub 22d, design §7.10).
19	 *
20	 * Gli asset vivono su disco PRIVATO (non esposto via symlink/URL pubblico):
21	 * ogni accesso al file passa di qui, che decide chi può vederlo. Due rami di
22	 * autorizzazione (design §7.10):
23	 *
24	 *  1. Richiesta firmata (signed URL temporaneo) → accesso concesso dalla firma
25	 *     stessa. È il meccanismo per l'embedding senza sessione e per la
26	 *     condivisione esterna (22g, gallery `/share/{token}` con token proprio).
27	 *  2. Utente autenticato nel pannello → si applica la policy sul proprietario
28	 *     dell'asset quando esiste (authz interna §7.1: A+B nativi, C on demand).
29	 *     Senza policy registrata sul proprietario, basta l'autenticazione.
30	 *
31	 * Il file è servito inline. Per i dischi locali si usa una BinaryFileResponse
32	 * (supporta le Range request → seeking di video/audio); per dischi remoti si
33	 * ricade sullo stream del filesystem.
34	 */
35	class AssetServeController
36	{
37	    /** Serve il file originale dell'asset. */
38	    public function show(Request $request, Media $media): Response
39	    {
40	        $this->authorizeAccess($request, $media);
41	
42	        return $this->serve($media, $media->getPathRelativeToRoot(), $media->mime_type);
43	    }
44	
45	    /**
46	     * Download multiplo come zip in streaming (22e). L'accesso è dato dal token
47	     * dello {@see AssetShare}: il token è il segreto, qui si verifica solo che lo
48	     * share esista e non sia scaduto. Streaming vero verso il browser, senza
49	     * buffering Livewire. Stessa rotta usata dalla condivisione esterna (22g).
50	     */
51	    public function downloadShareZip(string $token): StreamedResponse
52	    {
53	        $share = AssetShare::query()->where('token', $token)->first();
54	        abort_if($share === null || $share->isExpired(), 404);
55	
56	        // share protetto da password (22g): scaricabile solo dopo lo sblocco nella
57	        // gallery (gate condiviso via sessione, design §7.10). Gli share effimeri del
58	        // download multiplo (22e) non hanno password → nessun gate.
59	        abort_if($share->hasPassword() && session()->get($share->sessionUnlockKey()) !== true, 403);
60	
61	        $media = $share->media()->get();
62	        abort_if($media->isEmpty(), 404);
63	
64	        $name = 'assets-' . now()->format('Ymd-His') . '.zip';
65	
66	        return AssetZip::streamResponse($media, $name);
67	    }
68	
69	    /** Serve il poster/anteprima generato per l'asset (404 se assente). */
70	    public function preview(Request $request, Media $media): Response
71	    {
72	        $this->authorizeAccess($request, $media);
73	
74	        $path = $media->getCustomProperty(AssetPreview::PROPERTY);
75	        abort_unless(is_string($path) && $path !== '', 404);
76	
77	        return $this->serve($media, $path, 'image/jpeg');
78	    }
79	
80	    /**
81	     * Autorizza l'accesso al media. Vedi i due rami descritti sul controller.
82	     */
83	    private function authorizeAccess(Request $request, Media $media): void
84	    {
85	        if ($request->hasValidSignature()) {
86	            return;
87	        }
88	
89	        $user = $request->user();
90	        abort_if($user === null, 403);
91	
92	        // Proprietario morph dell'asset (es. Product). Si applica la sua policy
93	        // solo se ne esiste una registrata: il core non impone authz per-record,
94	        // la abilita quando il template la fornisce (shield / policy custom).
95	        $owner = $media->model;
96	        if ($owner !== null && Gate::getPolicyFor($owner) !== null) {
97	            abort_if(Gate::forUser($user)->denies('view', $owner), 403);
98	        }
99	    }
100	
101	    /**
102	     * Risposta inline per un path relativo al disco del media. Usa una
103	     * BinaryFileResponse (Range/seeking) sui dischi locali, lo stream del
104	     * filesystem altrimenti.
105	     */
106	    private function serve(Media $media, string $relativePath, ?string $mime): Response
107	    {
108	        $disk = Storage::disk($media->disk);
109	        abort_unless($disk->exists($relativePath), 404);
110	
111	        $headers = $mime !== null ? ['Content-Type' => $mime] : [];
112	
113	        // Disco locale: path assoluto risolvibile a un file reale → BinaryFileResponse,
114	        // che gestisce nativamente le Range request (seeking video/audio). Su dischi
115	        // remoti (es. s3) il path non è un file locale → stream del filesystem.
116	        $absolute = $disk->path($relativePath);
117	        if (is_file($absolute)) {
118	            return response()->file($absolute, $headers);
119	        }
120	
121	        return $disk->response($relativePath, $media->file_name, $headers, 'inline');
122	    }
123	}
