5	namespace AtrioTeam\DigitalHub\Assets\Support;
6	
7	use DateTimeInterface;
8	use Illuminate\Support\Facades\URL;
9	use Spatie\MediaLibrary\MediaCollections\Models\Media;
10	
11	/**
12	 * Fonte unica degli URL di accesso agli asset (digital-hub 22d, design §7.10).
13	 *
14	 * Gli asset stanno su disco privato e si servono attraverso la route gata
15	 * {@see \AtrioTeam\DigitalHub\Assets\Http\Controllers\AssetServeController}:
16	 * NON si usa più `Media::getUrl()` / `Storage::url()` (che richiederebbero un
17	 * disco pubblico). Le UI del pannello usano gli URL "normali" (gata via
18	 * sessione); le varianti `temporary*` producono signed URL temporanei per
19	 * l'embedding senza sessione e per il riuso esterno (condivisione 22g).
20	 */
21	class AssetUrl
22	{
23	    /** URL dell'originale, gato via sessione+policy. */
24	    public static function original(Media $media): string
25	    {
26	        return route('digital-hub.assets.show', ['media' => $media->getKey(), 'v' => self::version($media)]);
27	    }
28	
29	    /** URL del poster/anteprima, o null se l'asset non ne ha uno generato. */
30	    public static function preview(Media $media): ?string
31	    {
32	        if (! self::hasPreview($media)) {
33	            return null;
34	        }
35	
36	        return route('digital-hub.assets.preview', ['media' => $media->getKey(), 'v' => self::version($media)]);
37	    }
38	
39	    /** Signed URL temporaneo all'originale (embedding senza sessione / esterno). */
40	    public static function temporaryOriginal(Media $media, DateTimeInterface $expiresAt): string
41	    {
42	        return URL::temporarySignedRoute('digital-hub.assets.show', $expiresAt, ['media' => $media->getKey(), 'v' => self::version($media)]);
43	    }
44	
45	    /** Signed URL temporaneo al poster, o null se assente. */
46	    public static function temporaryPreview(Media $media, DateTimeInterface $expiresAt): ?string
47	    {
48	        if (! self::hasPreview($media)) {
49	            return null;
50	        }
51	
52	        return URL::temporarySignedRoute('digital-hub.assets.preview', $expiresAt, ['media' => $media->getKey(), 'v' => self::version($media)]);
53	    }
54	
55	    private static function hasPreview(Media $media): bool
56	    {
57	        $path = $media->getCustomProperty(AssetPreview::PROPERTY);
58	
59	        return is_string($path) && $path !== '';
60	    }
61	
62	    /**
63	     * Cache-buster: senza, sostituire il file (22i/14d) o rigenerare il poster
64	     * lascia l'URL invariata (stesso id media) e né la cache HTTP del browser
65	     * né il diffing DOM di Livewire (src testualmente identico) notano il
66	     * cambiamento — l'anteprima resta quella vecchia finché non si ricarica la
67	     * pagina. `updated_at` cambia a ogni replace/rielaborazione.
68	     */
69	    private static function version(Media $media): int
70	    {
71	        return $media->updated_at?->getTimestamp() ?? 0;
72	    }
73	}
