/**
 * Link pubblico permanente al singolo media (#33). `media` (id) come argument.
 *
 * Un'unica action per "pubblica" e "mostra il link": {@see AssetPublication::publish()}
 * è idempotente, quindi su un asset già pubblicato non rigenera nulla e si
 * limita a riaprire il modal con lo stesso URL. La conferma compare solo la
 * prima volta: è lì che si sta prendendo la decisione di rendere il file
 * accessibile a chiunque abbia il link.
 */
public function publicLinkAssetAction(): Action
{
    return Action::make('publicLinkAsset')
        ->label(__('digital-hub::assets.public_link'))
        ->icon(Heroicon::OutlinedGlobeAlt)
        ->iconButton()
        ->requiresConfirmation(fn (array $arguments): bool => ! $this->isAssetPublished($arguments))
        ->modalHeading(__('digital-hub::assets.public_link_heading'))
        ->modalDescription(__('digital-hub::assets.public_link_publish_description'))
        ->action(function (array $arguments): void {
            $media = $this->findOwnedMedia($arguments['media'] ?? null);
            if ($media === null) {
                return;
            }

            AssetPublication::publish($media);

            // Come per lo share (22g): il link col bottone "copia" vive in un
            // modal della page, perché le action delle notifiche Filament non
            // eseguono JS custom.
            $this->lastPublicUrl = AssetUrl::publicOriginal($media);
            $this->dispatch('open-modal', id: 'public-link');
        });
}

/**
 * Revoca il link pubblico di un media (#33). `media` (id) come argument.
 * Visibile solo se l'asset è pubblicato.
 */
public function revokePublicLinkAssetAction(): Action
{
    return Action::make('revokePublicLinkAsset')
        ->label(__('digital-hub::assets.public_link_revoke'))
        ->icon(Heroicon::OutlinedGlobeAlt)
        ->iconButton()
        ->color('danger')
        ->visible(fn (array $arguments): bool => $this->isAssetPublished($arguments))
        ->requiresConfirmation()
        ->modalHeading(__('digital-hub::assets.public_link_revoke_heading'))
        ->modalDescription(__('digital-hub::assets.public_link_revoke_description'))
        ->action(function (array $arguments): void {
            $media = $this->findOwnedMedia($arguments['media'] ?? null);
            if ($media === null) {
                return;
            }

            AssetPublication::revoke($media);

            Notification::make()->success()->title(__('digital-hub::assets.public_link_revoked'))->send();
        });
}

/** L'asset indicato dagli argument dell'action è pubblicato? */
private function isAssetPublished(array $arguments): bool
{
    $media = $this->findOwnedMedia($arguments['media'] ?? null);

    return $media !== null && AssetPublication::isPublished($media);
}

/**
 * Sposta un media in un'altra folder (o root). `media` (id) come argument.
 */
public function moveAssetAction(): Action

