25	    private function makeMedia(): Media
26	    {
27	        Storage::fake('assets');
28	
29	        $product = Product::create(['name' => ['it' => 'Tavolo']]);
30	
31	        return $product
32	            ->addMediaFromString($this->jpeg())
33	            ->usingFileName('photo.jpg')
34	            ->toMediaCollection('assets');
